def transform(grid):
    g = np.array(grid)
    H, W = g.shape
    wall = 2
    # cells reachable from border without crossing walls -> outside
    outside = np.zeros((H, W), bool)
    stack = [(y, x) for y in range(H) for x in range(W)
             if (y in (0, H-1) or x in (0, W-1)) and g[y, x] != wall]
    for p in stack:
        outside[p] = True
    while stack:
        y, x = stack.pop()
        for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
            ny, nx = y+dy, x+dx
            if 0 <= ny < H and 0 <= nx < W and not outside[ny, nx] and g[ny, nx] != wall:
                outside[ny, nx] = True
                stack.append((ny, nx))
    interior = (~outside) & (g != wall)
    out = g.copy()
    for y in range(H):
        for x in range(W):
            c = g[y, x]
            if c == 0 or c == wall or not outside[y, x]:
                continue
            dirs = []
            if y == 0: dirs.append((1, 0))
            if y == H-1: dirs.append((-1, 0))
            if x == 0: dirs.append((0, 1))
            if x == W-1: dirs.append((0, -1))
            for dy, dx in dirs:
                cy, cx = y+dy, x+dx
                entered = False
                painted = False
                while 0 <= cy < H and 0 <= cx < W:
                    if interior[cy, cx]:
                        entered = True
                        if g[cy, cx] != 0:
                            break
                        out[cy, cx] = c
                        painted = True
                    elif entered:
                        break
                    cy += dy; cx += dx
                if painted:
                    emit(out.copy(), f"Legend colour {c} at ({y},{x}) shoots inward and fills the diamond interior until an obstacle or the wall.")
    emit(out.copy(), "All legend rays drawn; final grid.")
    return out
